-- Fee receipts (docs/designs/fee-receipts): offline receipts against one registration's dues, oldest first; gapless FEEREC
-- numbers per centre and financial year; the database stamps the date, the number text and each line's GST, and proves the rest.
-- Head generated by prisma migrate diff.
-- CreateTable
CREATE TABLE "app"."receipt" (
    "id" BIGSERIAL NOT NULL,
    "centre_id" INTEGER NOT NULL,
    "registration_id" UUID NOT NULL,
    "period" TEXT NOT NULL,
    "number" BIGINT NOT NULL,
    "receipt_no" TEXT NOT NULL,
    "received_on" DATE NOT NULL,
    "mode" TEXT NOT NULL,
    "reference" TEXT,
    "instrument_date" DATE,
    "currency" CHAR(3) NOT NULL,
    "total" DECIMAL(14,2) NOT NULL,
    "idempotency_key" UUID NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'ACTIVE',
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "created_by" UUID NOT NULL,

    CONSTRAINT "receipt_pkey" PRIMARY KEY ("id")
);

