    "cgst" DECIMAL(14,2) NOT NULL,
    "sgst" DECIMAL(14,2) NOT NULL,
    "igst" DECIMAL(14,2) NOT NULL,

    CONSTRAINT "receipt_allocation_pkey" PRIMARY KEY ("id")
);

