-- ---------- Named checks (mirrored in src/server/receipts.ts) ----------
alter table app.receipt add constraint receipt_mode_check check (mode in ('CASH', 'CHEQUE', 'DD', 'BANK_TRANSFER', 'UPI', 'CARD'));
alter table app.receipt add constraint receipt_reference_check check ((mode = 'CASH') = (reference is null)
  and (reference is null or (reference = btrim(reference) and char_length(reference) between 1 and 50)));
alter table app.receipt add constraint receipt_instrument_date_check check ((mode in ('CHEQUE', 'DD')) = (instrument_date is not null));
alter table app.receipt add constraint receipt_total_check check (total > 0);
alter table app.receipt add constraint receipt_status_check check (status in ('ACTIVE', 'CANCELLED'));
alter table app.receipt add constraint receipt_currency_check check (currency ~ '^[A-Z]{3}$');
alter table app.receipt_allocation add constraint receipt_allocation_amount_check check (amount > 0);
alter table app.receipt_allocation add constraint receipt_allocation_tax_check check (taxable >= 0 and cgst >= 0 and sgst >= 0 and igst >= 0
  and taxable + cgst + sgst + igst = amount);

-- ---------- The Indian financial year (April-March) of a date, as numbering.ts financialYear() (C5, D9) ----------
create function app.financial_year(d date) returns text
language sql immutable set search_path = pg_catalog
as $$ select y::text || '-' || lpad(((y + 1) % 100)::text, 2, '0')
      from (select extract(year from d)::int - case when extract(month from d) < 4 then 1 else 0 end as y) t $$;

-- ---------- Outstanding, defined once (Z1, C6): gross minus the allocations of ACTIVE receipts. Invoker: the caller's RLS. ----------
create view app.fee_due_balance with (security_invoker = true) as
  select d.id as due_id, d.registration_id,
    coalesce(sum(a.amount) filter (where r.status = 'ACTIVE'), 0)::numeric(14,2) as paid,
    (d.gross - coalesce(sum(a.amount) filter (where r.status = 'ACTIVE'), 0))::numeric(14,2) as outstanding
  from app.fee_due d
    left join app.receipt_allocation a on a.due_id = d.id
    left join app.receipt r on r.id = a.receipt_id
  group by d.id;

-- ---------- Guards: rules only, so they bind every role. Nested ifs (plpgsql does not short-circuit AND); null-safe
-- comparisons; a missing or hidden source row refuses. Each message carries its constraint name. ----------
create function app.receipt_guard() returns trigger
language plpgsql security invoker set search_path = pg_catalog, app
as $$
declare cur bigint; code text;
begin
  -- the registration's money lock (fee-dues lock contract)
  perform pg_advisory_xact_lock(hashtext('fee-dues:' || new.registration_id::text));
  new.created_at := now();
  new.created_by := coalesce(app.session_user_id(), new.created_by);
  new.received_on := (now() at time zone 'Asia/Kolkata')::date;
  new.status := 'ACTIVE';
  if new.period is distinct from app.financial_year(new.received_on) then
    raise exception 'the period is the receipt date''s financial year: constraint "receipt_number_guard"' using errcode = '23514', constraint = 'receipt_number_guard';
  end if;
  -- the series current, under the row lock allocate() already holds
  select s.current into cur from app.number_series s
   where s.centre_id = new.centre_id and s.doc_type = 'FEEREC' and s.period = new.period for update;
  if not found or cur is distinct from new.number then
    raise exception 'the number is the series current: constraint "receipt_number_guard"' using errcode = '23514', constraint = 'receipt_number_guard';
  end if;
  select c.code into code from app.centre c where c.id = new.centre_id;
  if not found then
    raise exception 'the centre is not found: constraint "receipt_number_guard"' using errcode = '23514', constraint = 'receipt_number_guard';
  end if;
  -- DD-4 (PMC, NP-5): {centre code}/{yy}/{number}, at most 16 characters
  new.receipt_no := code || '/' || substr(new.period, 3, 2) || '/' || new.number::text;
  if char_length(new.receipt_no) > 16 then
    raise exception 'the receipt number is longer than 16 characters: constraint "receipt_length_guard"' using errcode = '23514', constraint = 'receipt_length_guard';
  end if;
  return new;
end $$;
create trigger receipt_guard before insert on app.receipt for each row execute function app.receipt_guard();

create function app.receipt_allocation_guard() returns trigger
language plpgsql security invoker set search_path = pg_catalog, app
as $$
declare
  r_reg uuid; r_centre int; r_currency text; r_at timestamptz;
  d_reg uuid; d_centre int; d_currency text; d_type int;
  owed numeric; rate numeric; hsn text;
  g_enabled boolean; g_supply text; g_in text; tax numeric;
begin
  select r.registration_id, r.centre_id, r.currency::text, r.created_at into r_reg, r_centre, r_currency, r_at
    from app.receipt r where r.id = new.receipt_id;
  if not found then
    raise exception 'the receipt is not found: constraint "receipt_allocation_guard"' using errcode = '23514', constraint = 'receipt_allocation_guard';
  end if;
  -- lines only in the receipt's own transaction (D15): now() is the transaction's start time
  if r_at is distinct from now() then
    raise exception 'lines are added only with their receipt: constraint "receipt_allocation_guard"' using errcode = '23514', constraint = 'receipt_allocation_guard';
  end if;
  perform pg_advisory_xact_lock(hashtext('fee-dues:' || r_reg::text));
  select d.registration_id, d.centre_id, d.currency::text, d.fee_type_id into d_reg, d_centre, d_currency, d_type
    from app.fee_due d where d.id = new.due_id;
  if not found or d_reg is distinct from r_reg or d_centre is distinct from r_centre or d_currency is distinct from r_currency
     or new.centre_id is distinct from r_centre then
    raise exception 'a line is a due of the receipt''s registration, in its currency: constraint "receipt_allocation_guard"' using errcode = '23514', constraint = 'receipt_allocation_guard';
  end if;
  select b.outstanding into owed from app.fee_due_balance b where b.due_id = new.due_id;
  if not found or new.amount > owed then
    raise exception 'a due is never paid beyond what is outstanding: constraint "receipt_over_guard"' using errcode = '23514', constraint = 'receipt_over_guard';
  end if;
  -- tax at receipt (DD-3): the fee type's rate and HSN/SAC; the centre's registration; GST in India only (INR)
  select t.gst_rate, t.hsn_sac into rate, hsn from app.fee_type t where t.id = d_type;
  if not found then
    raise exception 'the fee type is not found: constraint "receipt_tax_guard"' using errcode = '23514', constraint = 'receipt_tax_guard';
  end if;
  select c.gst_enabled, c.gst_supply, c.gstin into g_enabled, g_supply, g_in from app.centre c where c.id = r_centre;
  if not found then
    raise exception 'the centre is not found: constraint "receipt_tax_guard"' using errcode = '23514', constraint = 'receipt_tax_guard';
  end if;
  new.gst_rate := rate;
  new.hsn_sac := hsn;
  if g_enabled and r_currency = 'INR' then
    if g_supply is null or g_in is null then
      raise exception 'a GST-registered centre needs its supply and GSTIN: constraint "receipt_tax_guard"' using errcode = '23514', constraint = 'receipt_tax_guard';
    end if;
    new.taxable := round(new.amount * 100 / (100 + rate), 2);
    tax := new.amount - new.taxable;
    if g_supply = 'INTERSTATE' then
      new.cgst := 0; new.sgst := 0; new.igst := tax;
    else
      new.cgst := round(tax / 2, 2); new.sgst := tax - new.cgst; new.igst := 0;
    end if;
  else
    new.taxable := new.amount; new.cgst := 0; new.sgst := 0; new.igst := 0;
  end if;
  return new;
end $$;
create trigger receipt_allocation_guard before insert on app.receipt_allocation for each row execute function app.receipt_allocation_guard();

-- the total and at least one line, at commit (D15: lines exist only in their receipt's transaction)
create function app.receipt_total_check() returns trigger
language plpgsql security invoker set search_path = pg_catalog, app
as $$
declare n int; s numeric;
begin
  select count(*), coalesce(sum(a.amount), 0) into n, s from app.receipt_allocation a where a.receipt_id = new.id;
  if n = 0 or s is distinct from new.total then
    raise exception 'a receipt''s total is the sum of its lines: constraint "receipt_total_guard"' using errcode = '23514', constraint = 'receipt_total_guard';
  end if;
  return null;
end $$;
create constraint trigger receipt_total_commit after insert on app.receipt deferrable initially deferred
  for each row execute function app.receipt_total_check();

-- ---------- Immutability (F4 will open only status ACTIVE -> CANCELLED; lines never change) ----------
create trigger receipt_no_update_delete before update or delete on app.receipt for each row execute function app.ticket_immutable();
create trigger receipt_no_truncate before truncate on app.receipt for each statement execute function app.ticket_immutable();
create trigger receipt_allocation_no_update_delete before update or delete on app.receipt_allocation for each row execute function app.ticket_immutable();
create trigger receipt_allocation_no_truncate before truncate on app.receipt_allocation for each statement execute function app.ticket_immutable();

-- ---------- RLS: student.view reads (DD-7, PMC), fee.collect issues; update and delete never ----------
do $$
declare t text;
begin
  foreach t in array array['receipt', 'receipt_allocation'] loop
    execute format('alter table app.%I enable row level security', t);
    execute format('alter table app.%I force row level security', t);
    execute format('create policy %I on app.%I for select using (centre_id = any ((select app.scoped_centre_ids(''student.view''))::int[]))', t || '_select', t);
    execute format('create policy %I on app.%I for insert with check (centre_id = any ((select app.scoped_centre_ids(''fee.collect''))::int[]))', t || '_insert', t);
    execute format('create policy %I on app.%I for update using (false)', t || '_update', t);
    execute format('create policy %I on app.%I for delete using (false)', t || '_delete', t);
  end loop;
end $$;

-- ---------- Permission; the system administrator holds every permission (0013) ----------
insert into app.permission (key, description, sensitive) values
  ('fee.collect', 'Collect fees and issue receipts at a centre', false)
on conflict (key) do nothing;
insert into app.role_permission (role_id, permission_key) select id, 'fee.collect' from app.role where key = 'system_admin'
on conflict do nothing;

-- ---------- Grants: the id is reserved first; date, number text, status, tax and who/when are the guards' ----------
grant select, insert (id, centre_id, registration_id, period, number, mode, reference, instrument_date, currency, total, idempotency_key)
  on app.receipt to gems_app;
grant select, insert (receipt_id, centre_id, due_id, amount) on app.receipt_allocation to gems_app;
grant usage on sequence app.receipt_id_seq, app.receipt_allocation_id_seq to gems_app;
grant select on app.fee_due_balance to gems_app;
-- series rows created at rollover or activation (DD-4); current is not granted, so a new row starts at 0
grant insert (centre_id, doc_type, period, gap_rule) on app.number_series to gems_app;
